 "content": "def transform(grid):
    """Reflect the 4-pattern across the row indicated by the 6-pattern."""
    h, w = len(grid), len(grid[0])
    fours = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    out = [row[:] for row in grid]
    if not fours or not sixes:
        return out
    rmin, rmax = min(r for r, _ in fours), max(r for r, _ in fours)
    cmin, cmax = min(c for _, c in fours), max(c for _, c in fours)
    # The 6 shape marks the side of the 4-object on which its reflected copy lies.
    center6 = sum(r for r, _ in sixes) / len(sixes)
    center4 = sum(r for r, _ in fours) / len(fours)
    axis2 = rmin + rmax
    # Reflect the 4-cells across the line between the original and the marker.
    # The marker's far edge gives the reflected object's destination placement.
    if center6 > center4:
        for r, c in fours:
            nr = axis2 + 1 - r
            if 0 <= nr < h:
                out[nr][c] = 4
    else:
        for r, c in fours:
            nr = axis2 - 1 - r
            if 0 <= nr < h:
                out[nr][c] = 4
    for r, c in sixes:
        out[r][c] = 0
    # Copy takes priority over removing the marker.
    for r, c in fours:
        nr = axis2 + 1 - r if center6 > center4 else axis2 - 1 - r
        if 0 <= nr < h:
            out[nr][c] = 4
    return out
